//! Synthetic cartridge boot proof for phase 8.1.
//!
//! The boot ROM is generated by the crate and contains no copyrighted data. The
//! test proves the marker is reached with TMSS enabled while the SRAM byte,
//! mapper bank and TMSS latch are all observable.

#![allow(clippy::expect_used)]

use chronofork_backend_api::Backend;
use chronofork_core::InputFrame;
use chronofork_megadrive::{
    Cartridge, CartridgeSystem, MegadriveConfig, MegadriveFactory, Region, TmssModel, WindowMemory,
    boot_marker, cartridge_boot_rom, disassemble,
};

fn boot_machine(tmss: TmssModel) -> chronofork_megadrive::MegadriveBackend {
    MegadriveFactory::with_config(cartridge_boot_rom(), MegadriveConfig { video: None, tmss })
        .expect("boot cartridge")
        .create_machine()
        .expect("machine")
}

#[test]
fn boot_rom_unlocks_tmss_switches_bank_and_writes_sram() {
    let mut machine = boot_machine(TmssModel::Enabled);
    assert!(machine.tmss().locked());
    for _ in 0..40 {
        machine.step(InputFrame::NEUTRAL).expect("step");
    }
    assert_eq!(machine.cpu().pc(), boot_marker());
    assert_eq!(machine.cartridge().sram()[0], 0xC7);
    assert_eq!(machine.cartridge().banks()[0], 2);
    assert!(machine.cartridge().sram_visible());
    assert!(!machine.tmss().locked());
}

#[test]
fn boot_rom_also_reaches_the_marker_with_tmss_disabled() {
    let mut machine = boot_machine(TmssModel::Disabled);
    for _ in 0..40 {
        machine.step(InputFrame::NEUTRAL).expect("step");
    }
    assert_eq!(machine.cpu().pc(), boot_marker());
    assert_eq!(machine.cartridge().sram()[0], 0xC7);
}

#[test]
fn boot_state_survives_snapshot_and_restore() {
    let factory = MegadriveFactory::with_config(
        cartridge_boot_rom(),
        MegadriveConfig {
            video: None,
            tmss: TmssModel::Enabled,
        },
    )
    .expect("boot cartridge");
    let mut machine = factory.create_machine().expect("machine");
    for _ in 0..40 {
        machine.step(InputFrame::NEUTRAL).expect("step");
    }
    let snapshot = machine.snapshot().expect("snapshot");
    let mut restored = factory.create_machine().expect("machine");
    restored.restore(&snapshot).expect("restore");
    assert_eq!(restored.cpu().pc(), boot_marker());
    assert_eq!(restored.cartridge().sram()[0], 0xC7);
    assert_eq!(restored.cartridge().banks()[0], 2);
    assert!(!restored.tmss().locked());
    assert_eq!(
        restored.state_hash().expect("inspect digest"),
        snapshot.state_hash()
    );
}

#[test]
fn boot_header_is_a_valid_synthetic_cartridge() {
    let rom = cartridge_boot_rom();
    let cartridge = Cartridge::parse(rom.clone()).expect("parse");
    let header = cartridge.header();
    assert_eq!(header.system, CartridgeSystem::MegaDrive);
    assert_eq!(header.region, Region::parse("JUE").expect("region"));
    assert_eq!(header.serial, "GM 00000000-00");
    assert_eq!(header.rom_end, rom.len() as u32 - 1);
    assert_eq!(header.checksum_stored, header.checksum_computed);
}

#[test]
fn every_boot_instruction_is_a_supported_single_encoding() {
    let rom = cartridge_boot_rom();
    let program = &rom[0x200..0x226];
    let memory = WindowMemory::new(0x200, program);
    let decoded = disassemble(&memory, 0x200, 9).expect("decode boot program");
    assert_eq!(decoded.len(), 9);
    let expected = [
        (0x200, 0x203C_u16, 6), // MOVE.L #imm,D0
        (0x206, 0x23C0, 6),     // MOVE.L D0,(abs).L
        (0x20C, 0x7001, 2),     // MOVEQ #1,D0
        (0x20E, 0x13C0, 6),     // MOVE.B D0,(abs).L
        (0x214, 0x7002, 2),     // MOVEQ #2,D0
        (0x216, 0x13C0, 6),     // MOVE.B D0,(abs).L
        (0x21C, 0x70C7, 2),     // MOVEQ #-57,D0
        (0x21E, 0x13C0, 6),     // MOVE.B D0,(abs).L
        (0x224, 0x60FE, 2),     // BRA.S -2
    ];
    assert_eq!(boot_marker(), 0x224);
    for (record, (address, opcode, length)) in decoded.iter().zip(expected) {
        assert_eq!(record.address(), address);
        assert_eq!(record.opcode(), opcode);
        assert_eq!(record.length(), length);
    }
    // The self-loop really is the last instruction and loops to itself.
    assert_eq!(decoded.last().expect("last").address(), boot_marker());
}
